export interface QuestStory {
    id: number
    quests: QuestItem[]
}

export interface QuestItem {
    id: number
    name: string
    desc?: string
    nodes?: QuestNode[]
    startIds?: string[]
}

export type ImprType = "All" | "Any" | "Empathy" | "Chaos" | "Morality" | "Wisdom" | "Benefit"

export interface Dialogue {
    id: number
    content?: string
    voice?: string
    npc?: number
    speakerName?: string
    next?: number
    impr?: [number, ImprType, number]
    options?: DialogueOption[]
}

/**
 * 剧情媒体控制标记（PlayOrStopBGMNode 等），混排在对话列表中表示 BGM/音效起止，
 * 与普通 Dialogue 以是否存在 `type` 字段区分。
 */
export interface StoryMediaMarker {
    id: string
    type: string
    name: string
    resource?: string
}

export interface QuestNode {
    id: string
    type: string
    name: string
    next?: string[]
    srId?: number
    pos?: [number, number]
    /** BGM/音效资源键（PlayOrStopBGMNode 等媒体节点使用，映射到语音/乐谱数据集 CDN） */
    resource?: string
    /** 剧情内嵌视频 CDN 直链（可选，提供时在剧情页渲染视频播放器） */
    video?: string
    dialogues?: Dialogue[]
    answers?: DetectiveAnswer[]
    questions?: DetectiveQuestion[]
}

export interface DialogueOption {
    id: number
    content: string
    voice?: string
    npc?: number
    next?: number
    impr?: [number, ImprType, number]
    imprCheck?: [number, ImprType, number]
    options?: DialogueOption[]
}

export interface DetectiveQuestion {
    id: number
    name: string
    answers: number[]
    tips: string
}

export interface DetectiveAnswer {
    id: number
    qid: number
    name: string
    desc: string
    icon: string
}

