    "10124004#speaker": "Florist Owner",
    "10124006#speaker": "Florist Owner",
    "10124008#speaker": "Florist Owner",
    "10124102#speaker": "Florist Owner",
    "101259011#option": "What are you doing here?",
    "101259012#option": "Who are you?",
    "10125904#speaker": "Lady Nifle",
    "10125905#speaker": "Lady Nifle",
    "10125907#speaker": "Lady Nifle",
    "10125909#speaker": "Lady Nifle",
    "10125910#speaker": "Lady Nifle",
    "10125913#speaker": "Lady Nifle",
    "10125914#speaker": "Lady Nifle",
    "10125915#speaker": "Lady Nifle",
    "101259161#option": "I miss her terribly.",
    "101259162#option": "I refuse to accept this ending.",
    "10125917#speaker": "Lady Nifle",
    "10125918#speaker": "Lady Nifle",
    "10125919#speaker": "Lady Nifle",
    "10125920#speaker": "Lady Nifle",
    "10125921#speaker": "Lady Nifle",
    "101259211#option": "What's the Misty Sea like?",
    "10125922#speaker": "Lady Nifle",
    "101259231#option": "Can I go to the Misty Sea and bring her back?",
    "101259232#option": "Will she ever return to me?",
    "10125924#speaker": "Lady Nifle",
    "10125925#speaker": "Lady Nifle",
    "10125926#speaker": "Lady Nifle",
    "10125927#speaker": "Lady Nifle",
