    "11111204#speaker": "Ada's Voice",
    "11111206#speaker": "Ada's Voice",
    "11111207#speaker": "Ada's Voice",
    "11114008#option": "Is that a threat?",
    "11114010#option": "You're using me.",
    "11114012#option": "You don't trust me.",
