    "11118601#speaker": '"The High Priestess" Ada',
    "11118604#speaker": '"The High Priestess" Ada',
    "11118605#speaker": '"The High Priestess" Ada',
    "11118608#speaker": '"The High Priestess" Ada',
    "11118609#speaker": '"The High Priestess" Ada',
    "11118613#speaker": '"The High Priestess" Ada',
    "11118614#speaker": '"The High Priestess" Ada',
    "11118615#speaker": '"The High Priestess" Ada',
    "11118616#speaker": '"The High Priestess" Ada',
