    "12047904#speaker": "Ju et Yang",
    "12047910#speaker": "Ju et Yang",
    "12047911#option": "<I>J’accepte !</>",
    "12048202#option": "<I>Ne pas lui en vouloir</>",
    "12048203#option": "<I>Ne pas lui pardonner</>",
    "12048204#option": "<I>Lui laisser deviner</>",
